    #   tmp[i, j] = sum_k alpha * A[i, k] * B[k, j]
    for i in seq(0, ni):
        for j in seq(0, nj):
            tmp[i, j] = 0.0
            for k in seq(0, nk):
                tmp[i, j] += alpha * A[i, k] * B[k, j]

    # Second matrix multiplication and accumulation:
    #   D[i, j] = beta * D[i, j] + sum_k tmp[i, k] * C[k, j]
    for i in seq(0, ni):
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]
            for k in seq(0, nj):
                D[i, j] += tmp[i, k] * C[k, j]


def schedule_kernel_2mm() -> Procedure:
    p = kernel_2mm_unopt

    # --- Tiling in the tmp update to improve cache locality for A and B ---
    # Tile the j-loop in the first GEMM: j -> (jj, j)
    # This keeps the innermost j-iteration small, so each tile of B[k, j]
    # and tmp[i, j] fits better in cache.
    j0 = p.find_loop("j #0")
    p = divide_loop(p, j0, 32, ("jj", "j"), tail="guard")

    # --- Tiling in the D update to improve cache locality for C and D ---
    # After the previous transformation, the only remaining loop named 'j'
    # is in the second GEMM (the D update).
    j1 = p.find_loop("j")
    p = divide_loop(p, j1, 32, ("jj2", "j2"), tail="guard")

