    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # 1) Scale D by beta in-place.
    #    Innermost loop over j_d gives contiguous access to D.
    for i_d in seq(0, ni):
        for j_d in seq(0, nl):
            D[i_d, j_d] = beta * D[i_d, j_d]

    # 2) Initialize tmp to zero.
    #    Again, j_t is innermost for contiguous access.
    for i_t in seq(0, ni):
        for j_t in seq(0, nj):
